'use strict';
const KEY='bloom-v1';let state={};
state={profile:{},records:[],meds:[],appointments:[],questions:[],symptoms:[],...state};
const routes=[['overview','Overview'],['risk','Risk assessment'],['trends','Health journal'],['timeline','Pregnancy timeline'],['medications','Medications'],['appointments','Appointments'],['learn','Read & learn'],['chat','Ask Bloom'],['visit','Visit preparation'],['settings','Profile & privacy']];let model=null;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){return typeof accountSave==='function'?accountSave():false}
function notify(s){s=s.replaceAll('Saved on this device.','Changes queued. Check the account save status.').replaceAll('saved on this device.','queued for account storage.');$('#notice').textContent=s;setTimeout(()=>$('#notice').textContent='',6000)}
function heading(title,text){return `<h1>${title}</h1><p>${text}</p>`}function card(title,body){return `<section class="card"><h2>${title}</h2>${body}</section>`}function empty(s){return `<div class="empty">${s}</div>`}function field(name,label,type='text',value='',extra=''){return `<div><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function form(id,content,button){return `<form id="${id}">${content}<button>${button}</button></form>`}function vals(f){return Object.fromEntries(new FormData(f))}function date(s){return new Date(s).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}function gestation(){if(!state.profile.due)return null;return Math.floor((280-(new Date(state.profile.due+'T12:00:00')-new Date())/86400000)/7)}
$('#date').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'});$('#nav').innerHTML=routes.map(([r,n])=>`<a href="#${r}">${n}</a>`).join('');
const articles=[{title:'Your antenatal appointments',topic:'Pregnancy care',desc:'Understand what routine visits cover and prepare your questions.',url:'https://www.nhs.uk/pregnancy/your-pregnancy-care/your-antenatal-appointments/'},{title:'Medicines in pregnancy',topic:'Medication',desc:'Read trusted information and discuss medication decisions with your clinician.',url:'https://www.nhs.uk/pregnancy/keeping-well/medicines/'},{title:'Mental health in pregnancy',topic:'Wellbeing',desc:'Learn about emotional wellbeing and where to find support.',url:'https://www.nhs.uk/pregnancy/keeping-well/mental-health/'},{title:'Your health after birth',topic:'Postpartum',desc:'Explore recovery and health information after delivery.',url:'https://www.nhs.uk/pregnancy/labour-and-birth/after-the-birth/your-body/'}];
function overview(){let w=gestation(),last=state.records.at(-1);return heading(`Your journey${state.profile.name?', '+esc(state.profile.name):''}`, 'A little clarity for every step of your pregnancy.')+`<div class="grid">${card('One day at a time',`<span class="eyebrow">YOUR PERSONAL COMPANION</span><p>Keep your measurements, reminders, and appointment questions together.</p><a class="button" href="#risk">Check risk estimate</a>`).replace('class="card"','class="card hero"')}${card('Today’s focus',`<div class="row"><span>Medication schedules</span><b>${state.meds.length}</b></div><div class="row"><span>Appointment requests</span><b>${state.appointments.length}</b></div><div class="row"><span>Questions for your doctor</span><b>${state.questions.filter(q=>!q.done).length}</b></div><p class="muted">Reminders appear while this app is open.</p>`)}</div><div class="grid stats">${card('Pregnancy week',`<div class="big">${w!==null&&w>=0&&w<=42?w:'—'}</div><a href="#settings">${w===null?'Set your due date':'Update your profile'}</a>`)}${card('Latest risk estimate',`<div class="big">${last?esc(last.risk):'—'}</div><span class="muted">${last?date(last.at):'Complete your first assessment'}</span>`)}${card('Health journal',`<div class="big">${state.records.length}</div><a href="#trends">View saved measurements</a>`)}</div>${card('Built around your privacy',`<p>Your journal is saved to your account. Sign out on shared devices and check the save status before closing this page.</p>`)}`}
function risk(){return heading('Risk assessment','Enter your recorded measurements to estimate the UCI dataset’s risk category.')+`<div class="warning">This experimental model is not clinically validated. A low-risk estimate does not rule out a complication. Contact a qualified clinician for health concerns.</div><div class="grid">${card('Your measurements',form('riskForm',`<div class="grid">${field('Age','Age · years','number','', 'required min="1" max="100" step="1"')}${field('SystolicBP','Systolic BP · mmHg','number','','required min="1" max="300"')}${field('DiastolicBP','Diastolic BP · mmHg','number','','required min="1" max="200"')}${field('BS','Blood sugar · mmol/L','number','','required min="0.1" max="50" step="0.1"')}${field('BodyTemp','Temperature · °F','number','','required min="80" max="115" step="0.1"')}${field('HeartRate','Heart rate · bpm','number','','required min="1" max="250"')}</div><label class="check"><input type="checkbox" name="store"> Save this assessment to my account</label><p class="muted">Use the units shown. The form limits are input checks, not clinical thresholds.</p>`, 'Estimate risk'))}${card('Your result',`<div id="result">${empty(model?'Your estimate will appear here.':'Loading the model…')}</div><details><summary>About this model</summary><p>Random forest selected by grouped training cross-validation on UCI Maternal Health Risk. Duplicate rows were removed; equal measurement records stayed in one split. No diagnostic outcomes or gestational week are predicted.</p><div id="metrics"></div><a href="#model-results">Compare methods and scores</a><p><a href="model.json" download>Download current model</a></p></details>`)}</div>`}
function chart(){if(state.records.length<2)return empty('Save at least two assessments to see a blood pressure trend.');let rs=state.records.slice(-12),vs=rs.flatMap(r=>[r.SystolicBP,r.DiastolicBP]),lo=Math.min(...vs)-10,hi=Math.max(...vs)+10;let points=k=>rs.map((r,i)=>`${35+i*500/(rs.length-1)},${145-(r[k]-lo)/(hi-lo)*115}`).join(' ');return `<svg viewBox="0 0 570 185" class="chart" role="img" aria-label="Blood pressure trend, systolic and diastolic in mmHg"><text x="0" y="28">${hi}</text><text x="0" y="150">${lo}</text><line x1="35" y1="150" x2="545" y2="150" stroke="#dbe5e7"/><polyline points="${points('SystolicBP')}" fill="none" stroke="#176d79" stroke-width="3"/><polyline points="${points('DiastolicBP')}" fill="none" stroke="#d49747" stroke-width="3"/><text x="35" y="175">${date(rs[0].at)}</text><text x="425" y="175">${date(rs.at(-1).at)}</text></svg><small>Teal: systolic · Gold: diastolic · mmHg</small>`}
function trends(){return heading('Health journal','Keep a dated record of your measurements and how you feel.')+`<div class="grid">${card('Blood pressure over time',chart())}${card('Add a symptom note',form('symptomForm',`${field('day','Date','date',new Date().toLocaleDateString('en-CA'),'required')}<p><label for="note">What would you like to record?</label><textarea id="note" name="note" required maxlength="2000"></textarea></p>`,'Save note'))}</div>${card('Measurements',state.records.length?state.records.slice().reverse().map(r=>`<div class="row"><div><b>${date(r.at)} · ${esc(r.risk)}</b><p class="muted">BP ${r.SystolicBP}/${r.DiastolicBP} mmHg · Sugar ${r.BS} mmol/L · Temperature ${r.BodyTemp} °F · Pulse ${r.HeartRate} bpm · Age ${r.Age}</p></div><button class="danger" data-delete="records" data-id="${r.id}">Delete</button></div>`).join(''):empty('No saved measurements yet.'))}<div class="grid">${card('Symptom notes',state.symptoms.map(s=>`<div class="row"><div><b>${esc(s.day)}</b><p>${esc(s.note)}</p></div><button class="danger" data-delete="symptoms" data-id="${s.id}">Delete</button></div>`).join('')||empty('Your notes will appear here.'))}${card('Export your history','<p>Download your measurements for your own records or consultation.</p><button id="csv">Download CSV</button>')}</div>`}
function timeline(){let w=gestation();return heading('Pregnancy timeline','Your dates and plans, gathered in one place.')+`<div class="grid">${card('Your pregnancy',w===null?'<p>Add your expected delivery date to get started.</p><a class="button" href="#settings">Set due date</a>':`<span class="eyebrow">CURRENT WEEK</span><div class="big">${w>=0&&w<=42?w:'Outside pregnancy range'}</div><p>Expected delivery: ${esc(state.profile.due)}</p><div class="progress"><i style="width:${Math.min(100,Math.max(0,w/40*100))}%"></i></div><p class="muted">A date-based estimate. Your clinician can confirm your gestational age.</p>`)}${card('Upcoming plans',state.appointments.filter(a=>a.day>=new Date().toLocaleDateString('en-CA')).map(a=>`<div class="row"><div>${esc(a.day)} · ${esc(a.time)}<p>${esc(a.clinic)} · ${esc(a.status)}</p></div></div>`).join('')||empty('Add appointment plans in the Appointments section.'))}</div>${card('Preparing for each visit','<p>Your care schedule should come from your clinician. Save recommended tests and questions in visit preparation.</p><a class="button" href="#visit">Prepare for a visit</a>')}`}
function medications(){return heading('Medication reminders','Track medicines already prescribed to you. This app does not recommend medicines or doses.')+`<div class="grid">${card('Add a schedule',form('medForm',`<div class="grid">${field('name','Medication name','text','','required maxlength="100"')}${field('dose','Prescribed dose','text','','required maxlength="100"')}${field('time','Daily reminder time','time','','required')}</div><p class="muted">Daily reminders only. Alerts require the app to be open; they are not background push notifications.</p>`,'Add reminder'))}${card('Your schedules',state.meds.map(m=>`<div class="row"><div><b>${esc(m.name)}</b><p class="muted">${esc(m.dose)} · Daily ${esc(m.time)}</p><small>${m.taken?.includes(new Date().toLocaleDateString('en-CA'))?'Marked taken today':'Not marked taken today'}</small></div><div class="actions"><button data-taken="${m.id}" class="secondary">Mark taken</button><button data-delete="meds" data-id="${m.id}" class="danger">Remove</button></div></div>`).join('')||empty('No medication schedules yet.'))}</div>`}
function appointments(){return heading('Appointment planner','Save an appointment request and track your plans.')+`<div class="warning">Demo planner: requests are saved in your account and are not sent to a clinic. Contact the clinic directly to book.</div><div class="grid">${card('Plan an appointment',form('appointmentForm',`<div class="grid">${field('clinic','Clinic / gynecologist','text','','required maxlength="150"')}${field('day','Preferred date','date','','required min="'+new Date().toLocaleDateString('en-CA')+'"')}${field('time','Preferred time','time','','required')}</div><p><label for="reason">Reason / notes</label><textarea id="reason" name="reason" maxlength="2000"></textarea></p>`,'Save demo request'))}${card('Your appointments',state.appointments.map(a=>`<div class="row"><div><b>${esc(a.clinic)}</b><p>${esc(a.day)} · ${esc(a.time)}</p><span class="tag">${esc(a.status)}</span><p class="muted">${esc(a.reason)}</p></div><button data-delete="appointments" data-id="${a.id}" class="danger">Remove</button></div>`).join('')||empty('No planned appointments yet.'))}</div>`}
function learn(){return heading('Read & learn','A small library of trusted external resources. These are NHS articles, not original clinician-reviewed Bloom blogs.')+`<div class="grid">${articles.map(a=>card(a.title,`<span class="tag">${a.topic}</span><p>${a.desc}</p><a class="button" href="${a.url}" target="_blank" rel="noopener">Read on NHS</a>`)).join('')}</div>`}
function chat(){return heading('Ask Bloom','A curated help assistant for this app and its learning resources.')+card('How can I help?',`<p class="muted">This is a local, rule-based assistant. It cannot assess symptoms, diagnose conditions, or recommend medication.</p><div class="chat" id="messages"><div class="bubble">Try “How does risk prediction work?”, “medication reminders”, or “appointments”.</div></div>${form('chatForm',`<p><label for="message">Your question</label><input id="message" name="message" required maxlength="1000" autocomplete="off"></p>`,'Send')}`)}
function visit(){return heading('Visit preparation','Keep the questions you want to remember at your next consultation.')+`<div class="grid">${card('Add a question or task',form('questionForm',`<p><label for="question">Question / clinician-recommended task</label><textarea id="question" name="text" required maxlength="2000"></textarea></p>`,'Add to checklist'))}${card('Your checklist',state.questions.map(q=>`<div class="row"><label class="check"><input type="checkbox" data-question="${q.id}" ${q.done?'checked':''}>${esc(q.text)}</label><button data-delete="questions" data-id="${q.id}" class="danger">Remove</button></div>`).join('')||empty('Add your first question.'))}</div>${card('Your appointment report','<p>Download a printable HTML report with your profile, measurements, symptoms, medications, and questions. Open it and choose Print → Save as PDF.</p><button id="visitReport">Download report</button>')}`}
function settings(){return heading('Profile & privacy','Personalize your timeline and manage your account records.')+`<div class="grid">${card('Your profile',form('profileForm',`<div class="grid">${field('name','Preferred name','text',state.profile.name,'maxlength="100"')}${field('due','Expected delivery date','date',state.profile.due)}</div><p><label for="allergies">Allergies / relevant history</label><textarea id="allergies" name="allergies" maxlength="3000">${esc(state.profile.allergies)}</textarea></p>`,'Save profile'))}${card('Your data','<p>Records are saved by the backend under your account. Check the save status before closing the page.</p><p>You control your journal. Export a copy whenever you need it. Background notifications and caregiver sharing are not enabled.</p><div class="actions"><button id="export">Export all data</button><button class="danger" id="erase">Delete all records</button></div>')}</div>`}
const renderers={overview,risk,trends,timeline,medications,appointments,learn,chat,visit,settings};
function render(){if(typeof accountReady==='undefined'||!accountReady){$('#view').innerHTML='<p>Loading your account…</p>';return}if(!accountUser){$('#view').innerHTML=accountGate();return}const route=location.hash.slice(1)||'overview';$('#view').innerHTML=(renderers[route]||overview)();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));if(route==='risk'&&model&&$('#metrics'))$('#metrics').textContent=`Held-out macro F1: ${model.metrics.report['macro avg']['f1-score'].toFixed(2)}. High-risk recall: ${model.metrics.report['high risk'].recall.toFixed(2)}. Test records: ${model.metrics.test_rows}.`}
function predict(v){return inferModel(model,v)}
function download(name,text,type){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function report(){let body=`<h1>Bloom · Visit report</h1><p>Created ${esc(new Date().toLocaleString())}. Educational prototype; model results are not clinical diagnoses.</p><h2>Profile</h2><p>${esc(state.profile.name)} · Due date: ${esc(state.profile.due)}</p><p>${esc(state.profile.allergies)}</p><h2>Measurements</h2>`+state.records.map(r=>`<p>${date(r.at)}: BP ${r.SystolicBP}/${r.DiastolicBP} mmHg; blood sugar ${r.BS} mmol/L; temperature ${r.BodyTemp} °F; pulse ${r.HeartRate} bpm; age ${r.Age}; model estimate ${esc(r.risk)} (${esc(r.model)}).</p>`).join('')+`<h2>Symptoms</h2>`+state.symptoms.map(s=>`<p>${esc(s.day)}: ${esc(s.note)}</p>`).join('')+`<h2>Medications entered by user</h2>`+state.meds.map(m=>`<p>${esc(m.name)} · ${esc(m.dose)} · Daily ${esc(m.time)}</p>`).join('')+`<h2>Visit questions</h2>`+state.questions.map(q=>`<p>${q.done?'✓':'○'} ${esc(q.text)}</p>`).join('')+`<h2>Appointment plans (not clinic bookings)</h2>`+state.appointments.map(a=>`<p>${esc(a.clinic)} · ${esc(a.day)} ${esc(a.time)} · ${esc(a.reason)}</p>`).join('');if(typeof extraReportHtml==='function')body+=extraReportHtml();download('bloom-visit-report.html',`<!doctype html><html><head><meta charset="utf-8"><title>Bloom visit report</title><style>body{font:16px system-ui;max-width:850px;margin:40px auto;padding:20px;line-height:1.6}h2{border-bottom:1px solid #ddd}p{white-space:pre-wrap}</style></head><body>${body}</body></html>`,'text/html')}
document.addEventListener('submit',e=>{e.preventDefault();let f=e.target,v=vals(f),id=crypto.randomUUID();if(f.id==='riskForm'){if($('#result'))$('#result').innerHTML='';if(!model){notify('Model unavailable. Please reload when online.');return}let x=Object.fromEntries(model.features.map(k=>[k,Number(v[k])]));if(x.SystolicBP<=x.DiastolicBP){notify('Systolic pressure must be greater than diastolic pressure. Check your entry.');return}let outside=model.features.filter(k=>x[k]<model.ranges[k][0]||x[k]>model.ranges[k][1]);if(outside.length){$('#result').innerHTML=`<div class="warning">No estimate: ${outside.map(esc).join(', ')} outside the model’s training range. Check units and consult a clinician about your measurements.</div>`;return}let r=predict(x);$('#result').innerHTML=`<span class="eyebrow">DATASET CATEGORY ESTIMATE</span><div class="big">${esc(r)}</div><p>Based on six measurements. This does not diagnose a condition or establish that you are safe.</p><small>Model ${model.version}</small>`;if(v.store){state.records.push({...x,risk:r,id,at:new Date().toISOString(),model:model.version});save();notify('Assessment queued for account storage.')}}else if(f.id==='profileForm'){state.profile=v;save();render();notify('Profile queued for account storage. Check the save status.')}else if(f.id==='chatForm'){let s=v.message.toLowerCase(),answer='I can help with the app, reminders, appointments, and educational resources. I cannot evaluate symptoms or give treatment advice. For a medical question, speak with your clinician.';let link='';if(/risk|model|predict/.test(s))answer='The model predicts UCI low, mid, or high risk labels from age, blood pressure, blood sugar, temperature, and pulse. It is an experimental random forest, not a diagnosis. Gestational week and symptoms do not enter this model.';else if(/medic|dose|tablet/.test(s)){answer='Add the name, prescribed dose, and daily time under Medications. Reminders work only while this page is open. Discuss medication changes with your clinician.';link=articles[1].url}else if(/appoint|book/.test(s))answer='Appointments is a local demo planner. Saving a request does not contact a clinic. Contact your clinic directly to arrange and confirm a visit.';else if(/mental|mood|stress/.test(s)){answer='Bloom’s learning library links to NHS information on mental health in pregnancy. Discuss concerns with a qualified professional.';link=articles[2].url}else if(/report|export/.test(s))answer='Choose Download visit report to export your records as a printable HTML file. You can open it and use Print → Save as PDF.';$('#messages').insertAdjacentHTML('beforeend',`<div class="bubble user">${esc(v.message)}</div><div class="bubble">${esc(answer)}${link?`<p><a href="${link}" target="_blank" rel="noopener">NHS resource</a></p>`:''}</div>`);f.reset();$('#messages').scrollTop=$('#messages').scrollHeight}else{let map={medForm:'meds',appointmentForm:'appointments',questionForm:'questions',symptomForm:'symptoms'};let key=map[f.id];if(key){state[key].push({...v,id,...(key==='appointments'?{status:'Demo request — not sent'}:{}),...(key==='questions'?{done:false}:{})});save();render();notify('Saved on this device.')}}});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.delete){if(confirm('Remove this record?')){state[b.dataset.delete]=state[b.dataset.delete].filter(x=>x.id!==b.dataset.id);save();render()}}if(b.dataset.taken){let m=state.meds.find(m=>m.id===b.dataset.taken),d=new Date().toLocaleDateString('en-CA');m.taken=[...new Set([...(m.taken||[]),d])];save();render()}if(['report','visitReport'].includes(b.id))report();if(b.id==='export')download('bloom-data.json',JSON.stringify(state,null,2),'application/json');if(b.id==='erase'&&confirm('Permanently clear this account’s health records?')){state=initialState();ensureExtras();save();render();notify('Record deletion queued. Check the save status.')}if(b.id==='csv'){let keys=['at','Age','SystolicBP','DiastolicBP','BS','BodyTemp','HeartRate','risk','model'];download('bloom-measurements.csv',keys.join(',')+'\n'+state.records.map(r=>keys.map(k=>'"'+String(r[k]).replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv')}});
document.addEventListener('change',e=>{if(e.target.dataset.question){state.questions.find(q=>q.id===e.target.dataset.question).done=e.target.checked;save()}});
window.addEventListener('hashchange',render);render();fetch('model.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(m=>{model=m;if(location.hash==='#risk')render()}).catch(()=>notify('Model could not load. Risk estimates are unavailable.'));
let alerted=new Set();setInterval(()=>{if(typeof accountUser==='undefined'||!accountUser)return;let now=new Date(),day=now.toLocaleDateString('en-CA'),time=now.toTimeString().slice(0,5);state.meds.forEach(m=>{let key=day+m.id;if(m.time===time&&!alerted.has(key)&&!m.taken?.includes(day)){alerted.add(key);notify(`Medication reminder: ${m.name} · ${m.dose}. Follow your prescription.`)}})},15000);
if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
